nodes.content:
"""Parse vision/docs/file-tree.md (+ feature-map.md, decisions.md) into a node list. Enrichment lives in enrich.py."""
import re, json, sys

VISION = "/mnt/project-files/vision"
DOCS = f"{VISION}/docs"      # knowledge base (D-033); file-tree.md and feature-map.md moved here
md = open(f"{DOCS}/file-tree.md", encoding="utf-8").read()
fm = open(f"{DOCS}/feature-map.md", encoding="utf-8").read()
lines = md.split("\n")

version = re.search(r"# Agent OS: File tree \((v[\d.]+)\)", md).group(1)

# ---------- 1. tree block ----------
start = lines.index("```text", lines.index("## 1. Tree"))
end = lines.index("```", start + 1)
tree_lines = lines[start + 1:end]

nodes = []
stack = []  # (depth, node)
for raw in tree_lines:
    if not raw.strip():
        continue
    m = re.search(r"[├└]── ", raw)
    if m:
        depth = m.start() // 4
        rest = raw[m.end():]
    else:
        depth = -1
        rest = raw
    if "#" in rest:
        # a '#' inside a name never happens in this tree
        name, comment = rest.split("#", 1)
    else:
        name, comment = rest, ""
    name, comment = name.strip(), comment.strip()
    num = None
    nm = re.match(r"^\[([\d.]+)\]\s*", comment)
    if nm:
        num = nm.group(1)
        comment = comment[nm.end():]
    while stack and stack[-1][0] >= depth:
        stack.pop()
    parent = stack[-1][1] if stack else None
    if parent is None:
        path = name
    else:
        path = parent["path"].rstrip("/") + "/" + name
    is_folder = name.endswith("/")
    ntype = "folder" if is_folder else "file"
    node = {
        "id": None,
        "num": num,
        "name": name,
        "path": path,
        "type": ntype,
        "is_link": (bool(re.search(r"\.link(\.|/|$)", name)) and name != "subagents.link/") or bool(parent and parent["name"] == "subagents.link/"),  # *.links.json is a real file
        "is_placeholder": "[" in name,
        "parent": parent["id"] if parent else None,
        "children": [],
        "summary": comment,
    }
    # stable id: number if unique, otherwise path-based
    node["_depth"] = depth
    nodes.append(node)
    if parent:
        parent["children"].append(node)
    stack.append((depth, node))

# ids: "n-<num>" when that number appears once; otherwise path slug
from collections import Counter
cnt = Counter(n["num"] for n in nodes if n["num"])
def slug(p):
    s = re.sub(r"[^A-Za-z0-9._-]+", "-", p).strip("-")
    return s[:180]
for n in nodes:
    if n["num"] and cnt[n["num"]] == 1:
        n["id"] = "n-" + n["num"]
    else:
        n["id"] = "p-" + slug(n["path"])
seen = Counter()
for n in nodes:
    seen[n["id"]] += 1
    if seen[n["id"]] > 1:
        n["id"] += f"-{seen[n['id']]}"
for n in nodes:
    n["children"] = [c["id"] for c in n["children"]]
byid = {n["id"]: n for n in nodes}
for n in nodes:
    if n["parent"] and not isinstance(n["parent"], str):
        pass
# parent was set to parent's id before ids existed -> fix
tmp = {}
for n in nodes:
    for cid in n["children"]:
        tmp[cid] = n["id"]
for n in nodes:
    n["parent"] = tmp.get(n["id"])

# ---------- 2. object sections ----------
obj_start = lines.index("## 2. Objects")
obj_end = next(i for i in range(obj_start, len(lines)) if lines[i].startswith("## Changelog"))
sections = {}   # num -> section
retired = []
cur = None
in_code = False
code_buf = []
code_lang = ""
for ln in lines[obj_start + 1:obj_end]:
    if ln.startswith("### "):
        head = ln[4:].strip()
        lead = re.match(r"^((?:\[[\d.]+\][, ]*)+)", head)
        nums = re.findall(r"\[([\d.]+)\]", lead.group(1)) if lead else []
        title_name = re.search(r"`([^`]+)`", head)
        note = re.sub(r"^(\[[\d.]+\][, ]*)+", "", head)
        note = re.sub(r"`[^`]+`", "", note).strip()
        cur = {"nums": nums, "heading": head, "name": title_name.group(1) if title_name else None,
               "note": note.strip("() "), "items": [], "examples": []}
        if re.search(r"\((retired|moved to|moved:|merged into)", head):
            cur["retired"] = True
            retired.append(cur)
        for nnum in nums:
            if not cur.get("retired"):
                sections[nnum] = cur
        continue
    if cur is None:
        continue
    s = ln.strip()
    if s.startswith("```"):
        if not in_code:
            in_code = True
            code_lang = s[3:] or "text"
            code_buf = []
        else:
            in_code = False
            target = cur["items"][-1] if cur["items"] else None
            cur["examples"].append({"lang": code_lang, "body": "\n".join(code_buf),
                                    "after": target["label"] if target else None})
        continue
    if in_code:
        # strip the common 2-space indent used inside bullets
        code_buf.append(ln[2:] if ln.startswith("  ") else ln)
        continue
    if not s or s == "---":
        continue
    indent = len(ln) - len(ln.lstrip())
    if s.startswith("- "):
        body = s[2:]
        lm = re.match(r"^\*\*(.+?)\*\*:?\s*(.*)$", body)
        label, text = None, body
        if lm and (lm.group(1).endswith(":") or body[len(lm.group(0)) - len(lm.group(2)) - 1:].startswith(" ") or True):
            lab = lm.group(1).rstrip(":")
            # only treat as label when bold chunk is at start and followed by ':' (inside or after)
            if lm.group(1).endswith(":") or body.startswith("**" + lm.group(1) + "**:"):
                label, text = lab, lm.group(2).lstrip(": ").strip()
        if indent >= 2 and cur["items"]:
            cur["items"][-1]["sub"].append(text if not label else f"**{label}:** {text}")
        else:
            cur["items"].append({"label": label or "Note", "text": text, "sub": []})
    else:
        if cur["items"]:
            cur["items"][-1]["sub"].append(s)
        else:
            cur["items"].append({"label": "Note", "text": s, "sub": []})

# ---------- 3. decisions: docs/decisions.md (history log, D-033); fallback: the old [2.6] seed list ----------
import os
decisions = {}
if os.path.exists(f"{DOCS}/decisions.md"):
    dl = open(f"{DOCS}/decisions.md", encoding="utf-8").read().split("\n")
    for i, ln in enumerate(dl):
        hm = re.match(r"^#{2,4}\s+(D-\d{3})\s*[:.\-–]?\s*(.*)$", ln)
        if hm:
            body = []
            for l2 in dl[i + 1:]:
                if l2.startswith("#"):
                    break
                if l2.strip() and not l2.strip().startswith("<!--"):
                    body.append(l2.strip().lstrip("- "))
            first = next((b for b in body if re.match(r"(\*\*)?Decision", b)), body[0] if body else "")
            first = re.sub(r"^\*\*Decision:?\*\*:?\s*", "", first)
            decisions[hm.group(1)] = (hm.group(2).strip() + ": " + first).strip(": ") if first else hm.group(2).strip()
if not decisions and "2.6" in sections:
    seed = next((i for i in sections["2.6"]["items"] if i["label"].startswith("Seed entries")), None)
    for part in re.split(r" · ", seed["text"] if seed else ""):
        part = re.sub(r"^\*[^*]+\*\s*", "", part.strip())
        dm = re.match(r"(D-\d{3})\s+(.*)", part, re.S)
        if dm:
            decisions[dm.group(1)] = dm.group(2).strip()
decisions = dict(sorted(decisions.items()))

# ---------- 4. feature map ----------
features = {}  # num -> [ {area, logic, owner} ]
areas = []
area = None
for ln in fm.split("\n"):
    h = re.match(r"^## (\d+)\. (.+)$", ln)
    if h:
        area = h.group(2).strip()
        areas.append(area)
        continue
    if area and ln.startswith("|") and not ln.startswith("|---") and not ln.startswith("| Logic"):
        cells = [c.strip() for c in ln.strip("|").split("|")]
        if len(cells) < 2:
            continue
        logic, files = cells[0], cells[1]
        owner = cells[2] if len(cells) > 2 else ""
        for nnum in set(re.findall(r"\[([\d.]+)\]", files)):
            features.setdefault(nnum, []).append({"area": area, "logic": logic, "owner": owner})

json.dump({"version": version, "nodes": nodes, "sections": sections, "retired": retired,
           "decisions": decisions, "features": features, "areas": areas},
          open(sys.argv[1], "w"), indent=1, ensure_ascii=False)
print(len(nodes), "nodes;", len(sections), "section nums;", len(retired), "retired;",
      len(decisions), "decisions;", len(features), "feature nums")

"""Knowledge map for the Agent OS knowledge base (D-032).

Reads every doc in vision/docs/ (knowledge tags, see docs/README.md) plus the node list of
file-tree.data.json and works out which knowledge applies to which file or folder.

  python3 build_map.py                      # rebuild docs/index/knowledge-map.json, print problems + stale count
  python3 build_map.py --stale              # list nodes whose "How it works" summary is missing or stale, children first
  python3 build_map.py --context <node>     # everything needed to write one node's summary (node = id, [n] or path)
  python3 build_map.py --set <file.json>    # write {node: text} or {node: {text, keep: [...], sections: [{title, text}]}} into each node's index file (by = $BY or "knowledge-agent")
  python3 build_map.py --confirm <node>...  # the index file is right (also after editing it by hand): store the new basis, keep the text
  python3 build_map.py --orphans            # index files whose file or folder is gone (move them to archive/<date>/tree/)

The How it works of every node lives in its own Markdown file, `{name}.index.md` (tools/index_files.py),
in the mirror tree vision/tree/ while we plan. docs/index/summaries.json is retired (archive/2026-10-05/).

enrich.py imports build() to bake the map and the summaries into the explorer data.
"""
import json, re, os, sys, hashlib, datetime, fnmatch
import index_files as IF

HERE = os.path.dirname(os.path.abspath(__file__))
VISION = os.path.dirname(HERE)
DOCS = os.path.join(VISION, "docs")
INDEX = os.path.join(DOCS, "index")
MAP_PATH = os.path.join(INDEX, "knowledge-map.json")
LOCK_PATH = os.path.join(IF.TREE, ".index.lock")
DATA_PATH = os.path.join(VISION, "file-tree.data.json")

TAG = re.compile(r"<!--\s*k:\s*(.*?)\s*-->")
HEAD = re.compile(r"^(#{1,6})\s+(.*)$")


def h(s):
    return hashlib.sha1(s.encode("utf-8")).hexdigest()[:12]


def rel(path):
    return path[len("agent-os/"):] if path.startswith("agent-os/") else ("" if path == "agent-os" else path)


def glob_rx(pat):
    out, i = "", 0
    while i < len(pat):
        if pat.startswith("**", i):
            out += ".*"; i += 2
            if i < len(pat) and pat[i] == "/":
                out = out[:-2] + "(?:.*/)?"; i += 1
        elif pat[i] == "*":
            out += "[^/]*"; i += 1
        elif pat[i] == "?":
            out += "[^/]"; i += 1
        else:
            out += re.escape(pat[i]); i += 1
    return re.compile("^" + out + "/?$")


def parse_attrs(s):
    a = {}
    for part in s.split():
        if "=" in part:
            k, v = part.split("=", 1)
            a[k.strip()] = v.strip()
    return a


def doc_files():
    for root, dirs, files in os.walk(DOCS):
        dirs[:] = sorted(d for d in dirs if d not in ("inputs",))
        for f in sorted(files):
            if f.endswith(".md"):
                yield os.path.relpath(os.path.join(root, f), DOCS)


def read_doc(relpath):
    """-> (title, [entries]) for a topic doc; entries carry raw applies."""
    text = open(os.path.join(DOCS, relpath), encoding="utf-8").read()
    lines = text.split("\n")
    title = next((l.lstrip("# ").strip() for l in lines if l.startswith("# ")), relpath)
    heads = []  # (line_no, level, heading, attrs or None)
    fence = False
    for i, ln in enumerate(lines):
        if ln.strip().startswith("```"):
            fence = not fence
            continue
        if fence:
            continue
        m = HEAD.match(ln)
        if not m:
            continue
        attrs = None
        for j in range(i + 1, min(i + 3, len(lines))):
            t = TAG.search(lines[j])
            if t:
                attrs = parse_attrs(t.group(1)); break
            if lines[j].strip() and not lines[j].strip().startswith("<!--"):
                break
        heads.append((i, len(m.group(1)), m.group(2).strip(), attrs))
    entries = []
    for k, (i, lvl, head, attrs) in enumerate(heads):
        if attrs is None:
            continue
        end = len(lines)
        for (j, l2, _, a2) in heads[k + 1:]:
            if l2 <= lvl or a2 is not None:
                end = j; break
        body = "\n".join(l for l in lines[i + 1:end] if not TAG.search(l)).strip()
        entries.append({"id": attrs.get("id"), "doc": relpath, "heading": head, "level": lvl, "line": i + 1,
                        "applies_raw": [x for x in attrs.get("applies", "").split(",") if x],
                        "sources": [x for x in attrs.get("sources", "").split(",") if x],
                        "status": attrs.get("status", "decided"), "text": body, "hash": h(head + "\n" + body)})
    return title, entries, h(text)


def file_tree_sections():
    """file-tree.md object sections -> {heading: entry}; the file docs layer."""
    p = os.path.join(DOCS, "file-tree.md")
    if not os.path.exists(p):
        p = os.path.join(VISION, "file-tree.md")
    lines = open(p, encoding="utf-8").read().split("\n")
    out, cur, buf = {}, None, []
    try:
        start = lines.index("## 2. Objects")
    except ValueError:
        start = 0

    def flush():
        if cur:
            body = "\n".join(buf).strip()
            nums = re.findall(r"\[([\d.]+)\]", re.match(r"^((?:\[[\d.]+\][, ]*)+)", cur).group(1)) if re.match(r"^\[", cur) else []
            retired = bool(re.search(r"\((retired|moved to|moved:|merged into)", cur))
            out[cur] = {"id": "ft-" + (nums[0] if nums else h(cur)), "doc": "file-tree.md", "heading": cur, "nums": nums,
                        "status": "retired" if retired else "file-doc", "text": body, "hash": h(cur + "\n" + body)}
    for ln in lines[start + 1:]:
        if ln.startswith("## "):
            break
        if ln.startswith("### "):
            flush(); cur, buf = ln[4:].strip(), []
        elif cur is not None:
            buf.append(ln)
    flush()
    return out


def load_json(p, default):
    try:
        return json.load(open(p, encoding="utf-8"))
    except Exception:
        return default


def build(nodes, summaries=None):
    """nodes: explorer node dicts (id, num, name, path, type, parent, children, summary, purpose, section_heading)."""
    summaries = IF.load_all(nodes) if summaries is None else summaries
    byid = {n["id"]: n for n in nodes}
    bynum = {}
    for n in nodes:
        if n.get("num"):
            bynum.setdefault(n["num"], []).append(n["id"])
    problems = []

    def subtree(nid):
        out, st = [], [nid]
        while st:
            x = st.pop(); out.append(x); st += byid[x].get("children") or []
        return out

    def resolve(item):
        """-> (direct ids, inherited ids)"""
        m = re.fullmatch(r"\[([\d.]+)\](/\*\*)?", item)
        if m:
            ids = bynum.get(m.group(1), [])
            if not m.group(2):
                return ids, []
            inh = [d for i in ids for d in subtree(i)[1:]]
            return ids, inh
        if item.startswith("path:"):
            rx = glob_rx(item[5:])
            return [n["id"] for n in nodes if rx.match(rel(n["path"]))], []
        if item.startswith("name:"):
            rx = glob_rx(item[5:])
            return [n["id"] for n in nodes if rx.match(n["name"])], []
        if item in ("none", "root"):
            return [], []
        return None, None

    # topic docs
    docs, entries = {}, {}
    for rp in doc_files():
        if rp == "file-tree.md":
            continue
        title, ents, dh = read_doc(rp)
        docs[rp] = {"title": title, "hash": dh, "entries": []}
        for e in ents:
            if not e["id"]:
                problems.append(f"{rp}:{e['line']} tag without id"); continue
            if e["id"] in entries:
                problems.append(f"{rp}:{e['line']} duplicate id {e['id']} (also {entries[e['id']]['doc']})"); continue
            direct, inh = set(), set()
            for it in e["applies_raw"]:
                d, i = resolve(it)
                if d is None:
                    problems.append(f"{rp}:{e['line']} {e['id']}: bad applies item {it!r}"); continue
                if not d and it not in ("none", "root"):
                    problems.append(f"{rp}:{e['line']} {e['id']}: applies {it!r} matches nothing")
                direct |= set(d); inh |= set(i)
            e["nodes"], e["inherited_by"] = sorted(direct), sorted(inh - direct)
            entries[e["id"]] = e
            docs[rp]["entries"].append(e["id"])
    # file docs
    ft = file_tree_sections()
    file_docs = {}
    for head, s in ft.items():
        file_docs[s["id"]] = s
    node_fd = {}
    for n in nodes:
        sh = n.get("section_heading")
        if sh and sh in ft:
            node_fd[n["id"]] = ft[sh]["id"]
        elif n.get("num") and ("ft-" + n["num"]) in file_docs and file_docs["ft-" + n["num"]]["status"] != "retired":
            node_fd[n["id"]] = "ft-" + n["num"]
    # per node
    nmap = {}
    for n in nodes:
        nmap[n["id"]] = {"num": n.get("num"), "path": rel(n["path"]), "name": n["name"], "type": n["type"],
                         "parent": n.get("parent"), "children": n.get("children") or [],
                         "file_doc": node_fd.get(n["id"]), "same_as": n.get("same_as"), "direct": [], "inherited": []}
    for eid, e in entries.items():
        for nid in e["nodes"]:
            nmap[nid]["direct"].append(eid)
        for nid in e["inherited_by"]:
            nmap[nid]["inherited"].append(eid)
    for nid, x in nmap.items():
        n = byid[nid]
        fd = file_docs.get(x["file_doc"]) if x["file_doc"] else None
        kids = [h((summaries.get(c) or {}).get("text", "")) for c in x["children"]]
        basis_src = json.dumps([n.get("summary") or "", n.get("purpose") or "", fd["hash"] if fd else "",
                                sorted(entries[e]["hash"] for e in x["direct"]), kids])
        x["basis"] = h(basis_src)
        s = summaries.get(nid)
        x["summary_state"] = "missing" if not s else ("fresh" if s.get("basis") == x["basis"] else "stale")
        if not x["file_doc"] and not x["direct"] and not x["inherited"] and not x["same_as"]:
            problems.append(f"node {nid} ({x['path']}) has no file doc and no knowledge")
    # inputs
    inputs = load_json(os.path.join(DOCS, "inputs", "index.json"), {"inputs": []})
    inp = {}
    for i in inputs.get("inputs", []):
        inp[i["id"]] = {k: i.get(k) for k in ("at", "where", "file", "categories", "summary", "processed_into")}
        inp[i["id"]]["entries"] = []
    for eid, e in entries.items():
        for s in e["sources"]:
            if s.startswith("in-"):
                if s in inp:
                    inp[s]["entries"].append(eid)
                else:
                    problems.append(f"{e['doc']}:{e['line']} {eid}: unknown input {s}")
    return {
        "schema_version": 1,
        "built": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
        "docs": docs,
        "entries": {k: {kk: v for kk, v in e.items() if kk not in ("text",)} | {"chars": len(e["text"])} for k, e in entries.items()},
        "file_docs": {k: {kk: v for kk, v in s.items() if kk != "text"} for k, s in file_docs.items()},
        "nodes": nmap,
        "inputs": inp,
        "problems": problems,
    }, entries, file_docs


def post_order(nmap, root):
    out, st = [], [(root, False)]
    while st:
        x, done = st.pop()
        if done:
            out.append(x); continue
        st.append((x, True))
        for c in reversed(nmap[x]["children"]):
            st.append((c, False))
    return out


def find_node(nodes, key):
    key = key.strip()
    for n in nodes:
        if key in (n["id"], f"[{n.get('num')}]", n.get("num"), n["path"], rel(n["path"])):
            return n
    return None


def main():
    args = sys.argv[1:]
    data = load_json(DATA_PATH, None)
    _scanned = {n["id"] for n in data["nodes"] if n.get("scanned")}   # real files found by the scan have no index file (D-061)
    nodes = [dict(n, children=[c for c in n.get("children") or [] if c not in _scanned]) for n in data["nodes"] if n["id"] not in _scanned]
    summaries = IF.load_all(nodes)
    m, entries, file_docs = build(nodes, summaries)
    byid = {n["id"]: n for n in nodes}
    root = data.get("root") or nodes[0]["id"]
    if "--context" in args:
        n = find_node(nodes, args[args.index("--context") + 1])
        x = m["nodes"][n["id"]]
        print(f"# {x['path'] or 'agent-os/'}  ({n['id']}, [{n.get('num') or '-'}], {n['type']}, status {n.get('status')})")
        print(f"tree comment: {n.get('summary') or ''}\npurpose: {n.get('purpose') or ''}")
        if x["file_doc"]:
            fd = file_docs[x["file_doc"]]
            print(f"\n## File doc: file-tree.md / {fd['heading']}\n{fd['text']}")
        elif x["same_as"]:
            print(f"\n## Same layout as {x['same_as']} ({byid[x['same_as']]['path']})")
        for eid in x["direct"]:
            e = entries[eid]
            print(f"\n## Knowledge {eid} ({e['doc']} / {e['heading']}, {e['status']})\n{e['text']}")
        if x["inherited"]:
            print("\n## From folders above: " + "; ".join(f"{e} ({entries[e]['heading']})" for e in x["inherited"]))
        if x["children"]:
            print("\n## Children")
            for c in x["children"]:
                s = summaries.get(c, {}).get("text") or "(no summary yet) " + (byid[c].get("summary") or "")
                print(f"- {byid[c]['name']} [{byid[c].get('num') or '-'}]: {s}")
        if n["id"] in summaries:
            print(f"\n## Current summary ({x['summary_state']})\n{summaries[n['id']]['text']}")
            for sec in summaries[n["id"]].get("sections") or []:
                print(f"- {sec['title']}: {sec['text']}")
            for k in summaries[n["id"]].get("keep") or []:
                print(f"- keep in mind: {k}")
        return
    if "--set" in args or "--confirm" in args:
        # several workers may save at once: hold a lock and re-read the file inside it
        import fcntl
        os.makedirs(IF.TREE, exist_ok=True)
        lock = open(LOCK_PATH, "w"); fcntl.flock(lock, fcntl.LOCK_EX)
        summaries = IF.load_all(nodes)
        rendered = set()
        by = os.environ.get("BY", "knowledge-agent")
        at = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        if "--set" in args:
            new = load_json(args[args.index("--set") + 1], {})
            ids = []
            for k, t in new.items():
                n = find_node(nodes, k)
                if not n:
                    print("unknown node", k); continue
                rec = t if isinstance(t, dict) else {"text": t}
                keep = [k.strip() for k in rec.get("keep") or [] if k.strip()]
                secs = [{"title": x["title"].strip(), "text": x["text"].strip()} for x in rec.get("sections") or [] if x.get("title") and x.get("text")]
                # the six-heading files are read back with "What it is" as their text: store the same, so parents' bases hold
                text = next((x["text"] for x in secs if x["title"].lower() == "what it is"), None) or rec.get("text", "").strip()
                summaries[n["id"]] = {"text": text, "basis": "", "at": at, "by": by} | ({"keep": keep} if keep else {}) | ({"sections": secs} if secs else {})
                ids.append(n["id"]); rendered.add(n["id"])
        else:
            ids = [find_node(nodes, k)["id"] for k in args[args.index("--confirm") + 1:]]
        # bases depend on children's texts: recompute after all texts are in
        m, _, _ = build(nodes, summaries)
        for i in ids:
            rec = summaries.setdefault(i, {"text": "", "at": at, "by": by})
            rec["basis"] = m["nodes"][i]["basis"]
            if "--confirm" in args:
                rec["confirmed"] = at
            IF.save(byid[i], rec, None if i in rendered or not rec.get("body") else rec["body"])
        fcntl.flock(lock, fcntl.LOCK_UN); lock.close()
        m, _, _ = build(nodes, summaries)
        print(f"set {len(ids)}; stale now: {sum(1 for x in m['nodes'].values() if x['summary_state'] != 'fresh')}")
    os.makedirs(INDEX, exist_ok=True)
    json.dump(m, open(MAP_PATH, "w"), indent=1, ensure_ascii=False)
    order = post_order(m["nodes"], root)
    stale = [i for i in order if m["nodes"][i]["summary_state"] != "fresh"]
    if "--orphans" in args:
        for f in IF.orphans(nodes):
            print("tree/" + f)
        return
    if "--stale" in args:
        for i in stale:
            print(f"{i}\t{m['nodes'][i]['summary_state']}\t{m['nodes'][i]['path'] or 'agent-os/'}")
        return
    print(f"docs {len(m['docs'])}, entries {len(m['entries'])}, file docs {len(m['file_docs'])}, nodes {len(m['nodes'])}, inputs {len(m['inputs'])}")
    print(f"how it works files: {sum(1 for x in m['nodes'].values() if x['summary_state'] == 'fresh')} fresh, {len(stale)} missing or stale, {len(IF.orphans(nodes))} orphans (--orphans)")
    for p in m["problems"][:80]:
        print("problem:", p)
    if len(m["problems"]) > 80:
        print(f"... {len(m['problems']) - 80} more problems")


if __name__ == "__main__":
    main()

"""How it works and metadata of every file and folder, one file each (owner, 2026-10-05; names 2026-10-07, D-057).

A file's metadata files are named after it without its last extension and sit next to it: `vision.md` has
`vision.index.md` (How it works) and `vision.meta.json` (metadata). A folder `f/` has `f/f.index.md` and
`f/f.meta.json` inside it. A name with no extension stays whole (`.gitignore.index.md`). Where two files in one
folder, or a file and its folder, would share a name (`server/server.py` and `server/`), the file keeps its
extension (`server.py.index.md`). While we plan, the real files do not exist yet, so these files sit in a mirror
of the planned tree: vision/tree/agent-os/... Files and folders that already exist as drafts in this folder
(DRAFTS, DRAFT_DIRS: the people docs, the agents, the skills) keep theirs next to the draft, e.g.
vision/.claude/docs/README.index.md. When the repo is built they all move next to the real files.

Each index file:

    ---
    about: agent-os/agents/system/docs/README.md     # what it describes
    node: n-2.1                                       # its node on the File Tree page
    basis: 1a2b3c4d5e6f                               # hash of what it was written from (build_map.py)
    written: 2026-10-05T07:31:00Z
    by: knowledge-base-agent
    confirmed: 2026-10-05T09:40:00Z                   # optional: checked and still right
    ---
    # README.md

    ## What it is            (fixed headings, D-036) ... or ## Summary for files not moved yet
    ...
    ## Keep in mind
    - When you ..., ...

Each metadata file is JSON with the fields of the file-set plan (vision/plans/file-set.md), empty for now.

build_map.py reads and writes the index files through load_all() and save(); enrich.py reads the metadata files.
"""
import os, re

HERE = os.path.dirname(os.path.abspath(__file__))
VISION = os.path.dirname(HERE)
TREE = os.path.join(VISION, "tree")
ROOT = "agent-os"
FIXED = ["What it is", "Who looks after it", "When and how it changes", "Who uses it, and when", "Where it is mentioned", "Related knowledge"]
KEEP = "Keep in mind"
META_KEYS = ["about", "node", "basis", "written", "by", "confirmed"]
# nodes whose draft already exists in vision/ (by [n]): their index file sits next to the draft, not in the mirror
DRAFTS = {"2.1": ".claude/docs/README.md",
          "2.2": ".claude/docs/vision.md",
          "10.1.1.2": ".claude/agents/knowledge-base-agent.md",
          "10.1.1.3": ".claude/agents/project-ide-agent.md",
          "10.1.2.5.1": ".claude/skills/ide-build/SKILL.md",
          "10.1.2.6": ".claude/skills/ide-sync/SKILL.md",
          "10.1.5": ".claude/CLAUDE.md",
          "10.1.2.1": ".claude/skills/knowledge-intake/SKILL.md",
          "10.1.2.2": ".claude/skills/file-index/SKILL.md",
          "10.1.2.3": ".claude/skills/vision-doc/SKILL.md",
          "10.1.2.4": ".claude/skills/readme-doc/SKILL.md",
          "2.22": ".claude/docs/rebuild-prompt.md",
          "2.23": ".claude/docs/inputs-vision.md",
          "10.1.2.7": ".claude/skills/rebuild-prompt-doc/SKILL.md",
          "10.1.2.8": ".claude/skills/change-plan/SKILL.md"}
DRAFT_DIRS = {"10.1": ".claude/", "10.1.1": ".claude/agents/", "10.1.2": ".claude/skills/",
              "10.1.2.5": ".claude/skills/ide-build/"}


def _safe(seg):
    return re.sub(r",\s*", "+", seg.replace("|", "-"))


CLASH = set()   # ids of files that keep their extension: another family in the same folder has the same name


def family(name, keep_ext=False):
    """The family name of a file or folder: a file's name without its last extension, a folder's whole name."""
    nm = name.rstrip("/")
    if keep_ext or name.endswith("/"):
        return nm
    base, ext = os.path.splitext(nm)
    return base if base and ext else nm


def prepare(nodes):
    """Find the files whose family name is shared in their folder (with a sibling or with the folder itself)."""
    groups = {}
    for n in nodes:
        name = n.get("name") or ""
        if n.get("type") == "folder":
            groups.setdefault((n["id"], _safe(name.rstrip("/"))), []).append(None)
        elif n.get("parent") and not name.endswith(".index.md"):
            groups.setdefault((n["parent"], family(_safe(name))), []).append(n["id"])
    CLASH.clear()
    for ids in groups.values():
        if len(ids) > 1:
            CLASH.update(i for i in ids if i)


def family_rel(node, ending):
    """Path of one of the node's metadata files (ending ".index.md" or ".meta.json"), relative to vision/tree/."""
    p = node.get("path") or ROOT + "/"
    segs = [_safe(s) for s in p.rstrip("/").split("/") if s]
    if node.get("type") == "folder":
        return "/".join(segs + [segs[-1] + ending])
    if segs[-1].endswith(".index.md"):  # an index file has none of its own; (the retired pattern node [51] was its own example)
        return "/".join(segs)
    return "/".join(segs[:-1] + [family(segs[-1], node.get("id") in CLASH) + ending])


def index_rel(node):
    return family_rel(node, ".index.md")


def family_path(node, ending):
    num = node.get("num") or ""
    if num in DRAFTS:
        d, b = os.path.split(DRAFTS[num])
        return os.path.join(VISION, d, family(b, node.get("id") in CLASH) + ending)
    if num in DRAFT_DIRS:
        d = DRAFT_DIRS[num].rstrip("/")
        return os.path.join(VISION, d, os.path.basename(d) + ending)
    return os.path.join(TREE, family_rel(node, ending))


def index_path(node):
    return family_path(node, ".index.md")


def meta_path(node):
    return family_path(node, ".meta.json")


def index_file(node):
    """Where the node's index file is, relative to vision/ (shown on the page)."""
    return os.path.relpath(index_path(node), VISION)


def meta_file(node):
    return os.path.relpath(meta_path(node), VISION)


META_FIELDS = {"schema_version": 1, "about": "", "kind": "", "state": "", "status": "", "git": "", "secret": None,
               "generated_by": None, "writers": [], "readers": [], "changes_when": "", "related": [],
               "sources": {"decisions": [], "inputs": [], "notes": []}, "update_with": [], "inherits": [],
               "features": [], "views": [], "how_it_works": {}, "tree_number": ""}


def ensure_meta(nodes):
    """Write an empty metadata file for every node that has none (owner, 2026-10-07: empty for now)."""
    import json
    made = []
    for n in nodes:
        if (n.get("name") or "").endswith(".index.md"):
            continue
        f = meta_path(n)
        if not os.path.isfile(f):
            os.makedirs(os.path.dirname(f), exist_ok=True)
            with open(f, "w", encoding="utf-8") as fh:
                json.dump(META_FIELDS, fh, indent=2)
                fh.write("\n")
            made.append(f)
    return made


def split_front(text):
    m = re.match(r"^---\n(.*?)\n---[ \t]*\n?", text, re.S)
    if not m:
        return {}, text
    meta = {}
    for line in m.group(1).split("\n"):
        k, _, v = line.partition(":")
        if k.strip():
            meta[k.strip()] = v.strip()
    return meta, text[m.end():]


def parse_body(body):
    """-> text (the main summary), sections [{title, text}] for the fixed format, keep lines."""
    parts = re.split(r"^##[ \t]+(.+?)[ \t]*$", body, flags=re.M)
    secs = [(parts[i].strip(), parts[i + 1].strip()) for i in range(1, len(parts) - 1, 2)]
    keep, rest = [], []
    for t, x in secs:
        if t.lower() == KEEP.lower():
            keep = [re.sub(r"^\s*[-*]\s+", "", l).strip() for l in x.split("\n") if re.match(r"^\s*[-*]\s+", l)]
        else:
            rest.append((t, x))
    summ = [x for t, x in rest if t.lower() == "summary"]
    if summ:
        return {"text": summ[0], "sections": [], "keep": keep}
    if rest:
        first = next((x for t, x in rest if t.lower() == FIXED[0].lower()), rest[0][1])
        return {"text": first, "sections": [{"title": t, "text": x} for t, x in rest], "keep": keep}
    plain = re.sub(r"^#\s+.*$", "", body, flags=re.M).strip()
    return {"text": plain, "sections": [], "keep": keep}


def title_of(node):
    return node.get("name") or ROOT + "/"


def make_body(node, rec):
    out = [f"# {title_of(node)}", ""]
    secs = rec.get("sections") or []
    if secs:
        for s in secs:
            out += [f"## {s['title']}", "", s["text"].strip(), ""]
    else:
        out += ["## Summary", "", (rec.get("text") or "").strip(), ""]
    keep = [k for k in rec.get("keep") or [] if k.strip()]
    if keep:
        out += [f"## {KEEP}", ""] + [f"- {k.strip()}" for k in keep] + [""]
    return "\n".join(out).rstrip() + "\n"


def load(node):
    f = index_path(node)
    if not os.path.isfile(f):
        return None
    text = open(f, encoding="utf-8").read()
    meta, body = split_front(text)
    rec = parse_body(body)
    rec.update({"basis": meta.get("basis", ""), "at": meta.get("written", ""), "by": meta.get("by", ""), "body": body, "file": index_file(node)})
    if meta.get("confirmed"):
        rec["confirmed"] = meta["confirmed"]
    return rec


def load_all(nodes):
    prepare(nodes)
    out = {}
    for n in nodes:
        r = load(n)
        if r is not None:
            out[n["id"]] = r
    return out


def save(node, rec, body=None):
    """Write the node's index file. body=None renders it from rec (text, sections, keep)."""
    f = index_path(node)
    os.makedirs(os.path.dirname(f), exist_ok=True)
    meta = {"about": node.get("path") or ROOT + "/", "node": node["id"], "basis": rec.get("basis", ""),
            "written": rec.get("at", ""), "by": rec.get("by", ""), "confirmed": rec.get("confirmed", "")}
    front = "---\n" + "".join(f"{k}: {meta[k]}\n" for k in META_KEYS if meta.get(k)) + "---\n"
    text = front + (body if body is not None else make_body(node, rec))
    tmp = f + ".tmp"
    open(tmp, "w", encoding="utf-8").write(text)
    os.replace(tmp, f)
    return f


def orphans(nodes):
    """Index files under tree/ whose object is gone (renamed or removed): archive them."""
    prepare(nodes)
    want = {os.path.normpath(p(n)) for n in nodes for p in (index_path, meta_path)}
    out = []
    for d, _, fs in os.walk(TREE):
        out += [os.path.relpath(os.path.join(d, f), TREE) for f in fs if f.endswith((".index.md", ".meta.json")) and os.path.normpath(os.path.join(d, f)) not in want]
    return sorted(out)

// Smoke test of the File Tree page before publishing (ide-build step 5).
// Loads the page with a stand-in for the artifact runtime, opens items on a desktop and a phone width,
// and fails when the page throws, a tab is missing, or the page is wider than a phone screen.
//   node check_page.js <page dir> [out dir for screenshots] [node ids...]
// Needs Playwright with Chromium: PLAYWRIGHT (module path) and CHROMIUM (browser path) override the defaults.
const fs = require('fs'), path = require('path');
const { chromium } = require(process.env.PLAYWRIGHT || '/opt/node22/lib/node_modules/playwright');
const DIR = path.resolve(process.argv[2] || path.join(__dirname, '../explorer'));
const OUT = process.argv[3] && process.argv[3] !== '-' ? path.resolve(process.argv[3]) : null;
const IDS = process.argv.slice(4).length ? process.argv.slice(4) : ['n-0', 'n-2.1', 'n-53', 'n-10.1.1.3', 'n-11'];
const mock = () => {   // in-memory db, sample and user, the parts of window.claude the page uses
  const store = {}, subs = {};
  const snap = c => ({ docs: Object.entries(store[c] || {}).map(([id, v]) => ({ id, data: () => JSON.parse(JSON.stringify(v)) })) });
  const fire = c => (subs[c] || []).forEach(cb => setTimeout(() => cb(snap(c)), 5));
  const doc = (c, id) => ({
    set: async v => { (store[c] ||= {})[id] = JSON.parse(JSON.stringify(v)); fire(c); },
    update: async v => { if (!store[c]?.[id]) throw { code: 'not_found' }; Object.assign(store[c][id], v); fire(c); },
    delete: async () => { delete (store[c] || {})[id]; fire(c); },
  });
  const db = {
    collection: c => ({ onSnapshot: cb => { (subs[c] ||= []).push(cb); setTimeout(() => cb(snap(c)), 5); return () => {}; },
      add: async v => { const id = 'd' + Math.random().toString(36).slice(2, 8); await doc(c, id).set(v); return { id }; } }),
    doc: p => { const [c, id] = p.split('/'); return doc(c, id); },
  };
  const sample = async () => ({ text: 'ok', truncated: false }); sample.json = async () => null;
  window.claude = { use: async n => n === 'db' ? db : n === 'sample' ? sample : n === 'user' ? { id: async () => 'u1' } : null };
};
(async () => {
  const b = await chromium.launch(process.env.CHROMIUM ? { executablePath: process.env.CHROMIUM } :
    fs.existsSync('/opt/pw-browsers/chromium-1194/chrome-linux/chrome') ? { executablePath: '/opt/pw-browsers/chromium-1194/chrome-linux/chrome' } : {});
  const data = JSON.parse(fs.readFileSync(path.join(DIR, 'file-tree.data.json'), 'utf8'));
  const known = new Set(data.nodes.map(n => n.id));
  let bad = 0;
  for (const [label, vp] of [['desktop', { width: 1400, height: 900 }], ['phone', { width: 390, height: 844 }]]) {
    for (const id of IDS) {
      if (!known.has(id)) { console.log(`MISSING ${id}: not in the data`); bad++; continue; }
      const p = await b.newPage({ viewport: vp }); const errs = [];
      p.on('pageerror', e => errs.push(String(e)));
      await p.addInitScript('(' + mock + ')()');
      await p.route('http://local.test/**', r => { const f = path.join(DIR, new URL(r.request().url()).pathname);
        r.fulfill({ body: fs.readFileSync(f), contentType: f.endsWith('.json') ? 'application/json' : 'text/html; charset=utf-8' }); });
      await p.route(/fonts\.(googleapis|gstatic)\.com/, r => r.abort());
      await p.goto('http://local.test/file-tree-explorer.html#' + id);
      await p.waitForSelector('.tab', { timeout: 15000 }).catch(() => errs.push('no tabs rendered'));
      await p.waitForTimeout(400);
      const tabs = await p.$$eval('.tab', t => t.map(x => x.dataset.tab).filter(Boolean));
      for (const t of ['how', 'file']) if (tabs.includes(t)) {   // click it as a person would, even when the tab bar scrolls
        await p.evaluate(t => [...document.querySelectorAll(`.tab[data-tab="${t}"]`)].find(e => e.offsetParent)?.click(), t); await p.waitForTimeout(200); }
      const wide = await p.evaluate(() => document.documentElement.scrollWidth - innerWidth);
      const sel = await p.evaluate(() => document.querySelector('#tree .row.sel, #tree .row[aria-selected="true"]')?.dataset.id || '');
      const ok = !errs.length && tabs.length && (label === 'desktop' || wide <= 1);
      if (!ok) bad++;
      console.log(`${ok ? 'ok  ' : 'FAIL'} ${label} ${id} tabs=${tabs.join(',')} overflow=${wide}px selected=${sel} ${errs.join(' | ')}`);
      if (OUT) { fs.mkdirSync(OUT, { recursive: true }); await p.screenshot({ path: path.join(OUT, `${label}-${id}.png`) }); }
      await p.close();
    }
  }
  await b.close();
  console.log(bad ? `${bad} problem(s)` : 'page ok');
  process.exit(bad ? 1 : 0);
})().catch(e => { console.error('FAIL', e); process.exit(1); });

