#!/usr/bin/env python3
"""The project IDE server: the File Tree page on the owner's own machine, with Claude Code behind it.

It serves the same page that is published on claude.ai, from the repository, and gives
it what claude.ai gives it there:
- a store for the owner's notes, edits and messages, kept as JSON files in the
  repository (store_dir), so nothing waits on claude.ai;
- write-through: an edit to a file's text goes straight into that file, and an edit to
  How it works into the item's How it works file (vision.md has vision.index.md);
- the request box: each request runs as a Claude Code session (claude_bridge.py) and
  streams its progress to the page;
- voice input for the request boxes: a recording goes to Groq and comes back as text
  (voice.py).

Start it from the top of the repository:
    python3 apps/project-IDE/server/server.py
and open http://127.0.0.1:8765/ through an SSH tunnel. Never open the port to the
internet: whoever reaches the page can make Claude Code change files and run commands.
Settings are in server.config.json next to this file. Standard library only, plus
claude-agent-sdk for the request box.
"""
import json
import os
import re
import sys
import threading
import time
import uuid
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, unquote, urlparse

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
sys.dont_write_bytecode = True   # no __pycache__ in the repository
import claude_bridge  # noqa: E402
import voice  # noqa: E402

CONFIG = os.environ.get("IDE_CONFIG", os.path.join(HERE, "server.config.json"))
COLLECTIONS = {"nodes", "changes", "inputs"}       # what the page keeps (same as on claude.ai)
SAFE_ID = re.compile(r"^[A-Za-z0-9_.:@+~-]{1,200}$")


def now():
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def load_config():
    cfg = json.load(open(CONFIG, encoding="utf-8"))
    repo = os.path.realpath(os.path.join(HERE, cfg.get("repo", "../../..")))
    return cfg, repo


def load_secrets(cfg, repo):
    """Only the key names the config lists, read from the keys file on this machine. Values are never logged."""
    s = cfg.get("secrets") or {}
    path, names, env = os.path.join(repo, s.get("file", ".secrets/test/.env")), s.get("keys", []), {}
    if names and os.path.isfile(path):
        for line in open(path, encoding="utf-8"):
            k, sep, v = line.strip().partition("=")
            if sep and k.strip() in names:
                env[k.strip()] = v.strip().strip('"').strip("'")
    return env


class Store:
    """The page's store as files: <store_dir>/<collection>/<id>.json, one document per file."""

    def __init__(self, root):
        self.root, self.lock = root, threading.Lock()

    def _path(self, coll, doc_id):
        if coll not in COLLECTIONS or not SAFE_ID.match(doc_id):
            raise ValueError("bad collection or id")
        return os.path.join(self.root, coll, doc_id + ".json")

    def list(self, coll):
        if coll not in COLLECTIONS:
            raise ValueError("bad collection")
        d, out = os.path.join(self.root, coll), []
        if os.path.isdir(d):
            for f in sorted(os.listdir(d)):
                if f.endswith(".json"):
                    try:
                        out.append({"id": f[:-5], "data": json.load(open(os.path.join(d, f), encoding="utf-8"))})
                    except (OSError, ValueError):
                        pass
        return out

    def get(self, coll, doc_id):
        p = self._path(coll, doc_id)
        return json.load(open(p, encoding="utf-8")) if os.path.isfile(p) else None

    def set(self, coll, doc_id, data):
        p = self._path(coll, doc_id)
        with self.lock:
            os.makedirs(os.path.dirname(p), exist_ok=True)
            tmp = p + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=1, ensure_ascii=False)
            os.replace(tmp, p)
        return data

    def update(self, coll, doc_id, patch):
        with self.lock:
            cur = self.get(coll, doc_id) or {}
        cur.update(patch)
        return self.set(coll, doc_id, cur)


class WriteThrough:
    """Writes the owner's page edits of a file's text or its How it works into the repository."""

    def __init__(self, repo, data_file, never, planning=None):
        self.repo, self.data_file, self.never = repo, data_file, never
        self.planning = planning   # while we plan, the folder that holds the drafts and How it works files ("vision")
        self._nodes, self._mtime = {}, None

    def nodes(self):
        try:
            m = os.path.getmtime(self.data_file)
        except OSError:
            return {}
        if m != self._mtime:
            data = json.load(open(self.data_file, encoding="utf-8"))
            self._nodes, self._mtime = {n["id"]: n for n in data.get("nodes", [])}, m
        return self._nodes

    @staticmethod
    def _segs(node):
        segs = [s for s in (node.get("path") or "agent-os/").rstrip("/").split("/") if s]
        return [re.sub(r",\s*", "+", s.replace("|", "-")) for s in segs]

    def _safe(self, rel):
        p = os.path.realpath(os.path.join(self.repo, rel))
        inside = p.startswith(self.repo + os.sep)
        return p if inside and not any(b in rel for b in self.never) else None

    def file_of(self, node):
        if node.get("src_file"):             # the file the page showed: a draft, a repository file or a real file found on disk
            return self._safe(node["src_file"])
        if self.planning:                    # a planned file nobody has written: the edit waits in the page store for the sync
            return None
        segs = self._segs(node)[1:]          # drop the root name "agent-os"
        if node.get("type") != "file" or not segs or any("[" in s for s in segs):
            return None
        return self._safe("/".join(segs))

    @staticmethod
    def family(node, last):
        """The name an item's metadata files share: a file's name without its extension, a folder's own name.
        The build sets it on each item ("fam"); there a file whose name would clash keeps its extension."""
        if node.get("fam"):
            return node["fam"]
        if node.get("type") == "folder":
            return last
        base, ext = os.path.splitext(last)
        return base if base and ext else last

    def metadata_of(self, node, ending):
        """An item's metadata file (ending ".index.md" or ".meta.json"): next to a file, inside a folder."""
        segs = self._segs(node)
        where = segs[1:] if node.get("type") == "folder" else segs[1:-1]
        return self._safe("/".join(where + [self.family(node, segs[-1]) + ending]))

    def index_of(self, node):
        if self.planning:                    # How it works files sit in the planning folder (next to a draft, or in its mirror tree)
            return self._safe(os.path.join(self.planning, node["how_file"])) if node.get("how_file") else None
        return self.metadata_of(node, ".index.md")

    def apply(self, node_id, doc, before=None):
        """Writes what this save changed. A field the page saved before is not written again: the same
        document is saved again for a comment or a mark, and that must not undo what Claude Code wrote since."""
        n, fields, done = self.nodes().get(node_id), (doc or {}).get("fields") or {}, []
        old = (before or {}).get("fields") or {}
        if not n:
            return done
        text = fields.get("content")
        cut = isinstance(text, str) and "…(cut for the page" in text   # never write back a text the page only showed in part
        p = self.file_of(n) if isinstance(text, str) and not cut and text != old.get("content") else None
        if p and (not os.path.isfile(p) or open(p, encoding="utf-8").read() != text):
            os.makedirs(os.path.dirname(p), exist_ok=True)
            with open(p, "w", encoding="utf-8") as f:
                f.write(text)
            done.append(os.path.relpath(p, self.repo))
        how = fields.get("how_md")
        p = self.index_of(n) if isinstance(how, str) and how.strip() and how != old.get("how_md") else None
        if p:
            meta = {"about": n.get("path"), "node": n["id"]}
            if os.path.isfile(p):
                m = re.match(r"^---\n(.*?)\n---[ \t]*\n?", open(p, encoding="utf-8").read(), re.S)
                for line in (m.group(1).split("\n") if m else []):
                    k, _, v = line.partition(":")
                    if k.strip():
                        meta[k.strip()] = v.strip()
            meta.update({"written": now(), "by": "owner"})
            body = "---\n" + "".join(f"{k}: {v}\n" for k, v in meta.items() if v) + "---\n" + how.strip() + "\n"
            if not os.path.isfile(p) or open(p, encoding="utf-8").read().split("---\n", 2)[-1].strip() != how.strip():
                os.makedirs(os.path.dirname(p), exist_ok=True)
                with open(p, "w", encoding="utf-8") as f:
                    f.write(body)
                done.append(os.path.relpath(p, self.repo))
        return done


class App:
    def __init__(self):
        self.cfg, self.repo = load_config()
        self.page_dir = os.path.join(self.repo, self.cfg.get("page_dir", "apps/project-IDE/current-ui"))
        self.page = self.cfg.get("page", "file-tree-explorer.html")
        self.data = self.cfg.get("data", "file-tree.data.json")
        self.store = Store(os.path.join(self.repo, self.cfg.get("store_dir", "apps/project-IDE/data/page-store")))
        never = self.cfg.get("claude", {}).get("never", [".secrets"])
        self.write = WriteThrough(self.repo, os.path.join(self.page_dir, self.data), never, self.cfg.get("planning_dir")) if self.cfg.get("write_through", True) else None
        secrets = load_secrets(self.cfg, self.repo)
        self.voice = voice.Voice(self.cfg, secrets)
        # Claude Code gets only its own keys, never the voice key
        vkey = self.voice.cfg["key"]
        self.bridge = claude_bridge.Bridge(self.cfg, self.repo, {k: v for k, v in secrets.items() if k != vkey})

    def real_files(self):
        """id -> text of every real file the build found on disk ("scanned"), read now, so the page shows what is on disk."""
        out, never = {}, self.cfg.get("claude", {}).get("never", [".secrets"])
        try:
            nodes = json.load(open(os.path.join(self.page_dir, self.data), encoding="utf-8")).get("nodes", [])
        except (OSError, ValueError):
            return out
        for n in nodes:
            if not n.get("content_lazy") or not str(n.get("path", "")).startswith("agent-os/"):
                continue
            rel = n["path"][len("agent-os/"):]
            p = os.path.realpath(os.path.join(self.repo, rel))
            if not p.startswith(self.repo + os.sep) or any(b in rel for b in never) or not os.path.isfile(p):
                continue
            try:
                out[n["id"]] = open(p, encoding="utf-8").read()
            except (UnicodeDecodeError, OSError):
                pass
        return out


class Handler(BaseHTTPRequestHandler):
    app = None
    server_version = "ProjectIDE/1"

    def log_message(self, fmt, *args):  # quiet: one line per request on stderr only with -v
        if "-v" in sys.argv:
            super().log_message(fmt, *args)

    # ---------- helpers ----------
    def _send(self, code, body, ctype="application/json; charset=utf-8", extra=None):
        data = body if isinstance(body, bytes) else json.dumps(body, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-cache")
        for k, v in (extra or {}).items():
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(data)

    def _body(self):
        n = int(self.headers.get("Content-Length") or 0)
        return json.loads(self.rfile.read(n) or b"{}") if n else {}

    def _local(self):
        """Only this machine's own address: stops other sites in the browser from talking to the server."""
        host = (self.headers.get("Host") or "").split(":")[0]
        if host not in ("127.0.0.1", "localhost", "[::1]"):
            return False
        origin = self.headers.get("Origin")
        return not origin or urlparse(origin).hostname in ("127.0.0.1", "localhost", "::1")

    def _route(self):
        u = urlparse(self.path)
        return [unquote(p) for p in u.path.strip("/").split("/") if p], parse_qs(u.query)

    # ---------- GET ----------
    def do_GET(self):
        if not self._local():
            return self._send(403, {"error": "local only"})
        parts, q = self._route()
        a = self.app
        if not parts:
            return self._send(302, b"", extra={"Location": "/" + a.page})
        if parts[0] != "api":
            if parts == ["real-files.json"]:   # the texts of the real files, read fresh from the repository
                return self._send(200, json.dumps(a.real_files(), ensure_ascii=False).encode(), "application/json; charset=utf-8")
            if len(parts) == 1 and parts[0] in (a.page, a.data):
                ctype = "text/html; charset=utf-8" if parts[0].endswith(".html") else "application/json; charset=utf-8"
                return self._send(200, open(os.path.join(a.page_dir, parts[0]), "rb").read(), ctype)
            return self._send(404, {"error": "not found"})
        if parts[1:] == ["health"]:
            b = a.bridge
            return self._send(200, {"ok": True, "server": "project-ide", "agent": b.available, "agent_error": claude_bridge.SDK_ERROR,
                                    "repo": os.path.basename(a.repo), "claude_cwd": os.path.relpath(b.cwd, a.repo), "write_through": bool(a.write),
                                    "voice": a.voice.available, "voice_max_seconds": a.voice.cfg["max_seconds"]})
        if len(parts) == 3 and parts[1] == "store":
            try:
                return self._send(200, {"docs": a.store.list(parts[2])})
            except ValueError as e:
                return self._send(400, {"error": str(e)})
        if len(parts) == 4 and parts[1] == "agent" and parts[3] == "events":
            return self._events(parts[2], q)
        return self._send(404, {"error": "not found"})

    def _events(self, rid, q):
        run = self.app.bridge.runs.get(rid)
        if not run:
            return self._send(404, {"error": "no such run"})
        after = int(self.headers.get("Last-Event-ID", "-1")) + 1 if self.headers.get("Last-Event-ID") else int((q.get("after") or ["0"])[0])
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream")
        self.send_header("Cache-Control", "no-cache")
        self.end_headers()
        try:
            while True:
                events, done = run.wait(after)
                for e in events:
                    self.wfile.write(f"id: {e['n']}\ndata: {json.dumps(e, ensure_ascii=False)}\n\n".encode("utf-8"))
                after += len(events)
                if not events:
                    self.wfile.write(b": still working\n\n")
                self.wfile.flush()
                if done and after >= len(run.events):
                    break
        except (BrokenPipeError, ConnectionResetError):
            pass

    # ---------- writes ----------
    def _write(self, method):
        if not self._local():
            return self._send(403, {"error": "local only"})
        parts, _ = self._route()
        a = self.app
        if parts == ["api", "voice"] and method == "POST":
            return self._voice()
        try:
            body = self._body()
        except ValueError:
            return self._send(400, {"error": "bad JSON"})
        try:
            if len(parts) in (3, 4) and parts[:2] == ["api", "store"]:
                coll = parts[2]
                if method == "POST" and len(parts) == 3:
                    doc_id = time.strftime("%Y%m%d%H%M%S") + uuid.uuid4().hex[:6]
                    a.store.set(coll, doc_id, body)
                    return self._send(200, {"id": doc_id})
                doc_id = parts[3]
                before = a.store.get(coll, doc_id) if coll == "nodes" else None
                doc = a.store.set(coll, doc_id, body) if method == "PUT" else a.store.update(coll, doc_id, body)
                written = a.write.apply(doc_id, doc, before) if (a.write and coll == "nodes") else []
                return self._send(200, {"ok": True, "written": written})
            if parts == ["api", "agent"] and method == "POST":
                text = (body.get("text") or "").strip()
                if not text:
                    return self._send(400, {"error": "empty request"})
                node = {k: body.get(k) for k in ("node_id", "path", "name", "num")}
                known = (a.write.nodes().get(node["node_id"]) if a.write else None) or {}
                node.update({k: known[k] for k in ("type", "fam") if known.get(k)})
                # the Delete button: Claude Code may delete exactly this item without a second click
                target = a.bridge.delete_target(body["delete"]) if body.get("delete") else None
                run = a.bridge.start(text, node, body.get("session"), body.get("input_id"), delete=target)
                return self._send(200, {"run": run.id})
            if len(parts) == 4 and parts[1] == "agent" and parts[3] == "answer":
                return self._send(200, {"ok": a.bridge.answer(parts[2], body.get("id"), body.get("allow"))})
            if len(parts) == 4 and parts[1] == "agent" and parts[3] == "stop":
                return self._send(200, {"ok": a.bridge.stop(parts[2])})
        except ValueError as e:
            return self._send(400, {"error": str(e)})
        except RuntimeError as e:
            return self._send(503, {"error": str(e)})
        return self._send(404, {"error": "not found"})

    def _voice(self):
        """The raw recording in the body; its text back. The audio is not kept."""
        n = int(self.headers.get("Content-Length") or 0)
        if n > self.app.voice.cfg["max_bytes"]:
            return self._send(413, {"error": "recording too large"})
        audio = self.rfile.read(n) if n else b""
        try:
            return self._send(200, self.app.voice.transcribe(audio, self.headers.get("Content-Type")))
        except ValueError as e:
            return self._send(400, {"error": str(e)})
        except RuntimeError as e:
            return self._send(503, {"error": str(e)})

    def do_POST(self):
        self._write("POST")

    def do_PUT(self):
        self._write("PUT")

    def do_PATCH(self):
        self._write("PATCH")


def main():
    app = App()
    Handler.app = app
    host, port = app.cfg.get("host", "127.0.0.1"), int(os.environ.get("IDE_PORT") or app.cfg.get("port", 8765))
    if host not in ("127.0.0.1", "localhost", "::1"):
        sys.exit("Refusing to listen on " + host + ": the page can run Claude Code, so it stays on this machine. Use an SSH tunnel.")
    srv = ThreadingHTTPServer((host, port), Handler)
    print(f"Project IDE on http://{host}:{port}/  (repo {app.repo}; Claude Code in {os.path.relpath(app.bridge.cwd, app.repo)}"
          + ("" if app.bridge.available else f"; request box off: {claude_bridge.SDK_ERROR}") + ")", flush=True)
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        pass


if __name__ == "__main__":
    main()

"""Runs the owner's requests from the File Tree page as Claude Code sessions.

One request is one run. Claude Code starts in the system folder (agents/system/),
so the system's CLAUDE.md, agents and skills in agents/system/.claude/ load as its
own (there is no CLAUDE.md at the top of the repository). A follow-up passes the
previous session id and continues the same conversation.

Every step Claude Code wants to take is checked first:
- anything that touches the keys folder is refused;
- when the owner pressed Delete on the page, deleting exactly that item (and its How it
  works file) goes ahead without a second click;
- a file outside the repository waits for the owner's click on the page;
- a tool or command that is not on the allow list in server.config.json waits for
  the owner's click too (push, delete, installs, network tools ...).

A run streams events to the page (text, steps, approval requests, the result with its
cost and time) and is logged as one JSON file in the project IDE agent's log folder.
"""
import asyncio
import hashlib
import json
import os
import shlex
import subprocess
import threading
import time
import uuid

try:
    from claude_agent_sdk import (AssistantMessage, ClaudeAgentOptions, ClaudeSDKClient, HookMatcher,
                                  PermissionResultAllow, PermissionResultDeny, ResultMessage, TextBlock,
                                  ToolUseBlock)
    SDK_ERROR = None
except ImportError as e:  # the page still works without it, only the request box is off
    SDK_ERROR = f"claude-agent-sdk is not installed ({e})"

FILE_ARGS = {"Read": "file_path", "Edit": "file_path", "Write": "file_path", "MultiEdit": "file_path",
             "NotebookEdit": "notebook_path", "Glob": "path", "Grep": "path", "LS": "path"}

APPEND = """You are working for the owner through the project IDE page on their own server.
Their request comes from the File Tree page, about one file or folder of the repository.
- Follow the system's CLAUDE.md: file the request with knowledge-intake like any owner message, and finish a round that changed files as it says (rebuild the page with ide-build, commit).
- Never push: pushing waits for the owner's click. Never open the keys folder.
- Answer in plain, short words, as you would in a chat with the owner. Say what you changed."""


def now():
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def short(text, n=160):
    text = " ".join(str(text).split())
    return text if len(text) <= n else text[:n - 1] + "…"


class Run:
    """One request: its events, its open approval questions and its result."""

    def __init__(self, rid, text, node, session, delete=None):
        self.id, self.text, self.node, self.session = rid, text, node, session
        self.delete = delete         # repo path the owner deleted with the Delete button, or None
        self.events, self.done, self.result = [], False, None
        self.cond = threading.Condition()
        self.pending = {}            # approval id -> asyncio future
        self.asked = []              # every step that waited for the owner, in full, for the log
        self.loop = self.client = None
        self.started = time.time()

    def emit(self, kind, **data):
        with self.cond:
            self.events.append({"n": len(self.events), "type": kind, "at": now(), **data})
            self.cond.notify_all()

    def wait(self, after, timeout=15.0):
        """Events after the first `after` ones, waiting up to `timeout` seconds for new ones."""
        with self.cond:
            if len(self.events) <= after and not self.done:
                self.cond.wait(timeout)
            return self.events[after:], self.done

    def finish(self):
        with self.cond:
            self.done = True
            self.cond.notify_all()


class Bridge:
    def __init__(self, cfg, repo, env=None):
        self.cfg = cfg.get("claude", {})
        self.repo = os.path.realpath(repo)
        self.cwd = os.path.join(self.repo, self.cfg.get("cwd", "agents/system"))
        self.env = env or {}
        self.log_dir = os.path.join(self.repo, cfg.get("log_dir", "agents/system/logs/subagents/project-ide-agent"))
        self.store_dir = cfg.get("store_dir", "apps/project-IDE/data/page-store")
        self.runs = {}

    @property
    def available(self):
        return SDK_ERROR is None

    # ---------- the page's side ----------
    def start(self, text, node, session=None, input_id=None, delete=None):
        if SDK_ERROR:
            raise RuntimeError(SDK_ERROR)
        rid = time.strftime("%Y%m%d-%H%M%S") + "-" + uuid.uuid4().hex[:6]
        run = Run(rid, text, node or {}, session, delete)
        self.runs[rid] = run
        threading.Thread(target=lambda: asyncio.run(self._run(run, input_id)), daemon=True).start()
        return run

    def answer(self, rid, aid, allow):
        run = self.runs.get(rid)
        fut = run and run.pending.pop(aid, None)
        if not fut:
            return False
        run.loop.call_soon_threadsafe(lambda: fut.done() or fut.set_result(bool(allow)))
        return True

    def stop(self, rid):
        run = self.runs.get(rid)
        if not run or run.done or not run.client:
            return False
        asyncio.run_coroutine_threadsafe(run.client.interrupt(), run.loop)
        return True

    # ---------- checks before every step ----------
    def _inside(self, path):
        p = os.path.realpath(path if os.path.isabs(path) else os.path.join(self.cwd, path))
        return p == self.repo or p.startswith(self.repo + os.sep)

    def delete_target(self, rel):
        """The repository path of an item deleted on the page, checked: inside the repository, not the top, never the keys folder."""
        rel = str(rel or "").strip().lstrip("/")
        rel = rel[len("agent-os/"):] if rel.startswith("agent-os/") else rel
        p = os.path.realpath(os.path.join(self.repo, rel))
        if not rel or any(b in rel for b in self.cfg.get("never", [".secrets"])) or not p.startswith(self.repo + os.sep) or "[" in rel:
            raise ValueError("This item cannot be deleted from the page.")
        return os.path.relpath(p, self.repo)

    def metadata_files(self, rel, node=None):
        """The metadata files that sit next to a deleted file: its How it works and Details files, named without
        the file's extension (the build gives the name as "fam"). A folder keeps its own inside, so none."""
        rel = rel.rstrip("/")
        node = node or {}
        if os.path.isdir(os.path.join(self.repo, rel)) or node.get("type") == "folder" or str(node.get("name") or "").endswith("/"):
            return []
        base, ext = os.path.splitext(os.path.basename(rel))
        fam = node.get("fam") or (base if base and ext else os.path.basename(rel))
        return [os.path.join(os.path.dirname(rel), fam + e) for e in (".index.md", ".meta.json")]

    def _only_deletes(self, cmd, rel, node=None):
        """True when the command is one rm or git rm of the deleted item or its metadata files, by absolute path."""
        if any(ch in cmd for ch in ";&|`$<>()\n"):
            return False
        try:
            words = shlex.split(cmd)
        except ValueError:
            return False
        if words[:2] == ["git", "rm"]:
            words = words[2:]
        elif words[:1] == ["rm"]:
            words = words[1:]
        else:
            return False
        flags = [w for w in words if w.startswith("-")]
        paths = [w for w in words if not w.startswith("-")]
        if not paths or any(f not in ("-r", "-R", "-f", "-rf", "-fr", "-q", "--quiet", "--cached", "--ignore-unmatch", "--") for f in flags):
            return False
        root = os.path.join(self.repo, rel).rstrip(os.sep)
        extra = [os.path.join(self.repo, m) for m in self.metadata_files(rel, node)]
        for w in paths:
            if not os.path.isabs(w):
                return False
            p = os.path.normpath(w)
            if not (p == root or p in extra or p.startswith(root + os.sep)):
                return False
        return True

    def check(self, tool, args, run=None):
        """None to let the permission rules decide, or (decision, reason) with decision deny, allow or ask."""
        key = FILE_ARGS.get(tool)
        target = str(args.get(key) or "") if key else str(args.get("command") or "") if tool == "Bash" else ""
        for bad in self.cfg.get("never", [".secrets"]):
            if bad in target:   # the path or the command, not the text being written: docs may name the keys folder
                return "deny", f"Nothing from the page may touch {bad}."
        if tool == "Bash" and run is not None and run.delete and self._only_deletes(str(args.get("command") or ""), run.delete, run.node):
            return "allow", "The owner deleted this with the Delete button on the page."
        if key and args.get(key) and not self._inside(args[key]):
            return "ask", "This is outside the repository."
        if tool == "Bash":
            cmd = args.get("command", "")
            for word in self.cfg.get("ask_owner", []):
                if word in cmd:
                    return "ask", f"'{word.strip()}' waits for the owner."
        return None

    def _options(self, run):
        async def guard(inp, tool_use_id, ctx):
            verdict = self.check(inp.get("tool_name", ""), inp.get("tool_input") or {}, run)
            if not verdict:
                return {}
            decision, why = verdict
            return {"hookSpecificOutput": {"hookEventName": "PreToolUse",
                                           "permissionDecision": decision, "permissionDecisionReason": why}}

        async def ask_owner(tool, args, ctx):
            verdict = self.check(tool, args, run)
            if verdict and verdict[0] == "deny":
                return PermissionResultDeny(message=verdict[1])
            if verdict and verdict[0] == "allow":
                return PermissionResultAllow()
            aid = uuid.uuid4().hex[:8]
            fut = asyncio.get_running_loop().create_future()
            run.pending[aid] = fut
            what = args.get("command") or args.get(FILE_ARGS.get(tool, ""), "") or json.dumps(args)[:200]
            run.emit("approval", id=aid, tool=tool, summary=short(what), reason=(verdict or (None, ""))[1])
            try:
                allow = await asyncio.wait_for(fut, self.cfg.get("approval_timeout_s", 600))
            except asyncio.TimeoutError:
                allow = False
            run.pending.pop(aid, None)
            run.asked.append({"tool": tool, "what": str(what)[:2000], "reason": (verdict or (None, ""))[1], "allow": allow})
            run.emit("answered", id=aid, allow=allow, summary=short(f"{tool}: {what}"))
            if allow:
                return PermissionResultAllow()
            return PermissionResultDeny(message="The owner did not allow this step.")

        return ClaudeAgentOptions(
            cwd=self.cwd,
            add_dirs=[self.repo],
            setting_sources=["project", "local"],
            skills="all",
            system_prompt={"type": "preset", "preset": "claude_code", "append": APPEND},
            permission_mode="default",
            allowed_tools=self.cfg.get("allow", []),
            can_use_tool=ask_owner,
            hooks={"PreToolUse": [HookMatcher(matcher=None, hooks=[guard])]},
            model=self.cfg.get("model") or None,
            max_turns=self.cfg.get("max_turns") or None,
            max_budget_usd=self.cfg.get("max_budget_usd") or None,
            resume=run.session or None,
            env=dict(self.env),
        )

    def _prompt(self, run, input_id):
        n = run.node
        where = n.get("path", "the repository")
        label = f"{n.get('name', '')} [{n['num']}]" if n.get("num") else n.get("name", "")
        lines = [f"The owner wrote this on the File Tree page, on {where} ({label}):", "", run.text, ""]
        if run.delete:
            target = os.path.join(self.repo, run.delete)
            both = " ".join([target] + [os.path.join(self.repo, m) for m in self.metadata_files(run.delete, run.node)])
            lines += ["The owner pressed Delete on the page for this item and confirmed it. Follow \"Deleting an item\" in the ide-sync skill, "
                      "keeping in mind any note the owner wrote above.",
                      f"Delete the item itself with exactly this command, run on its own with nothing before or after it: "
                      f"`git rm -r -q --ignore-unmatch {both}`, and `rm -rf {both}` for what git does not track. "
                      "Those two go ahead without a second click; deleting anything else waits for the owner's click.", ""]
        if input_id:
            lines.append(f"The page saved it as {self.store_dir}/inputs/{input_id}.json. When you have filed it, "
                         "set that file's \"status\" to \"processed\" and \"processed_into\" to what it changed.")
        return "\n".join(lines)

    # ---------- the run ----------
    def _git(self, *args):
        try:
            out = subprocess.run(["git", "-c", "core.quotepath=off", *args], cwd=self.repo, capture_output=True, text=True, timeout=30)
            return out.stdout if out.returncode == 0 else None
        except Exception:
            return None

    def _hash(self, rel):
        try:
            with open(os.path.join(self.repo, rel), "rb") as f:
                return hashlib.sha1(f.read()).hexdigest()
        except OSError:
            return None

    def _dirty(self, head):
        """Files that differ from `head`: changed, deleted or new (committed or not)."""
        names = set((self._git("diff", "--name-only", head) or "").splitlines()) if head else set()
        names |= set((self._git("ls-files", "--others", "--exclude-standard") or "").splitlines())
        return {p for p in names if not any(b in p for b in self.cfg.get("never", [".secrets"]))}

    def _snapshot(self):
        """HEAD and the content of every file that already differed from it, to tell afterwards what a run changed."""
        head = (self._git("rev-parse", "HEAD") or "").strip() or None
        return head, {p: self._hash(p) for p in self._dirty(head)}

    def _changed(self, snap):
        """Files the run changed, also when Claude Code committed them."""
        head, before = snap
        now_dirty = self._dirty(head)
        return sorted({p for p in now_dirty if p not in before or self._hash(p) != before[p]} | (set(before) - now_dirty))

    async def _run(self, run, input_id):
        run.loop = asyncio.get_running_loop()
        snap = self._snapshot()
        run.emit("start", run=run.id, session=run.session)
        try:
            async with ClaudeSDKClient(options=self._options(run)) as client:
                run.client = client
                await client.query(self._prompt(run, input_id))
                async for msg in client.receive_response():
                    if isinstance(msg, AssistantMessage):
                        for b in msg.content:
                            if isinstance(b, TextBlock) and b.text.strip():
                                run.emit("text", text=b.text)
                            elif isinstance(b, ToolUseBlock):
                                arg = b.input.get("command") or b.input.get(FILE_ARGS.get(b.name, ""), "") or b.input.get("skill", "") or b.input.get("description", "")
                                run.emit("tool", tool=b.name, summary=short(f"{b.name} {arg}".strip()))
                    elif isinstance(msg, ResultMessage):
                        run.session = msg.session_id or run.session
                        run.result = {"text": msg.result or "", "cost_usd": msg.total_cost_usd, "duration_ms": msg.duration_ms,
                                      "turns": msg.num_turns, "session": run.session, "is_error": msg.is_error, "subtype": msg.subtype}
                        run.emit("result", **run.result)
        except Exception as e:
            run.emit("error", text=short(f"{type(e).__name__}: {e}", 400))
        changed = self._changed(snap)
        run.emit("end", changed=changed, seconds=round(time.time() - run.started, 1))
        run.finish()
        self._log(run, changed)

    def _log(self, run, changed):
        try:
            day = os.path.join(self.log_dir, run.id[:8])
            os.makedirs(day, exist_ok=True)
            rec = {"run": run.id, "at": now(), "node": run.node, "request": run.text, "delete": run.delete, "result": run.result, "changed": changed,
                   "steps": [e.get("summary") for e in run.events if e["type"] in ("tool", "answered")], "asked": run.asked}
            with open(os.path.join(day, run.id + ".json"), "w", encoding="utf-8") as f:
                json.dump(rec, f, indent=1, ensure_ascii=False)
        except OSError:
            pass

"""Voice input for the page's request boxes: a recording in, its text out, through Groq.

The page records up to five minutes in the browser and posts the audio to api/voice.
This module sends it to Groq's speech-to-text API, trying the models listed in
server.config.json ("voice.models") in order. A model that answers with a rate limit is
skipped until its wait is over; an error moves on to the next model. The key is read from
the keys file on this machine (secrets.keys lists GROQ_API_KEY) and never leaves the server.
Standard library only.
"""
import json
import threading
import time
import urllib.error
import urllib.request
import uuid

DEFAULTS = {
    "url": "https://api.groq.com/openai/v1/audio/transcriptions",
    "models": ["whisper-large-v3-turbo", "whisper-large-v3"],
    "key": "GROQ_API_KEY",
    "max_seconds": 300,
    "max_bytes": 25 * 1024 * 1024,   # Groq's limit for a direct upload on the free tier
    "language": None,                # None: Groq detects the language
    "timeout_s": 120,
}
EXT = {"audio/webm": "webm", "audio/ogg": "ogg", "audio/mp4": "m4a", "audio/mpeg": "mp3", "audio/wav": "wav", "audio/x-wav": "wav"}


class Voice:
    def __init__(self, cfg, secrets):
        self.cfg = {**DEFAULTS, **(cfg.get("voice") or {})}
        self.key = secrets.get(self.cfg["key"])
        self.cooldown = {}   # model -> time before which it is skipped
        self.lock = threading.Lock()

    @property
    def available(self):
        return bool(self.key and self.cfg["models"])

    def transcribe(self, audio, ctype):
        """Returns {"text", "model"}; raises ValueError for a bad recording, RuntimeError when every model failed."""
        if not self.available:
            raise RuntimeError(f"voice is off: {self.cfg['key']} is not in the keys file")
        if not audio:
            raise ValueError("empty recording")
        if len(audio) > self.cfg["max_bytes"]:
            raise ValueError("recording too large")
        ctype = (ctype or "audio/webm").split(";")[0].strip()
        now, errors = time.time(), []
        with self.lock:
            ready = [m for m in self.cfg["models"] if self.cooldown.get(m, 0) <= now]
        # every model resting: try the one whose wait ends first rather than refuse
        order = ready or sorted(self.cfg["models"], key=lambda m: self.cooldown.get(m, 0))[:1]
        for model in order:
            try:
                return {"text": self._call(model, audio, ctype), "model": model}
            except urllib.error.HTTPError as e:
                wait = _retry_after(e) if e.code == 429 else (60 if e.code >= 500 else 0)
                if wait:
                    with self.lock:
                        self.cooldown[model] = time.time() + wait
                errors.append(f"{model}: {e.code} {_message(e)}")
            except (urllib.error.URLError, TimeoutError, OSError, ValueError) as e:
                errors.append(f"{model}: {e}")
        raise RuntimeError("transcription failed: " + "; ".join(errors))

    def _call(self, model, audio, ctype):
        fields = {"model": model, "response_format": "json", "temperature": "0"}
        if self.cfg.get("language"):
            fields["language"] = self.cfg["language"]
        body, boundary = _multipart(fields, "recording." + EXT.get(ctype, "webm"), ctype, audio)
        req = urllib.request.Request(self.cfg["url"], data=body, method="POST", headers={
            "Authorization": "Bearer " + self.key,
            "Content-Type": "multipart/form-data; boundary=" + boundary,
            "User-Agent": "project-ide/1"})
        with urllib.request.urlopen(req, timeout=self.cfg["timeout_s"]) as r:
            return (json.loads(r.read() or b"{}").get("text") or "").strip()


def _multipart(fields, filename, ctype, data):
    b = uuid.uuid4().hex
    out = []
    for k, v in fields.items():
        out.append(f'--{b}\r\nContent-Disposition: form-data; name="{k}"\r\n\r\n{v}\r\n'.encode())
    out.append(f'--{b}\r\nContent-Disposition: form-data; name="file"; filename="{filename}"\r\nContent-Type: {ctype}\r\n\r\n'.encode())
    out += [data, f"\r\n--{b}--\r\n".encode()]
    return b"".join(out), b


def _retry_after(e):
    try:
        return max(5, min(3600, float(e.headers.get("retry-after") or 60)))
    except (TypeError, ValueError):
        return 60


def _message(e):
    try:
        return (json.loads(e.read() or b"{}").get("error") or {}).get("message", "")[:200]
    except Exception:
        return ""

